  public ControlsWindow(PetWindow p){
   pet=p;Title="Odd2U • Your companion";var area=SystemParameters.WorkArea;MinWidth=720;MinHeight=740;Width=Math.Max(MinWidth,area.Width/2);Height=area.Height;Left=area.Right-Width;Top=area.Top;WindowStartupLocation=WindowStartupLocation.Manual;Background=Ui.Canvas;Foreground=Ui.Ink;FontFamily=new FontFamily("Segoe UI");FontSize=14;Resources=Ui.Resources();
