   var body=new Grid{Margin=new Thickness(0,0,0,12)};Grid.SetRow(body,1);root.Children.Add(body);body.ColumnDefinitions.Add(new ColumnDefinition());body.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(14)});body.ColumnDefinitions.Add(new ColumnDefinition());
   var play=new Grid();play.RowDefinitions.Add(new RowDefinition());play.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});body.Children.Add(play);
   var hero=new Grid();var preview=new Viewport3D{Width=220,Height=220,IsHitTestVisible=false,Camera=pet.Scene.View.Camera.Clone()};preview.Children.Add(new ModelVisual3D{Content=((ModelVisual3D)pet.Scene.View.Children[0]).Content});hero.Children.Add(new Viewbox{Child=preview,Stretch=Stretch.Uniform,Margin=new Thickness(8,18,8,6)});var label=Ui.Text("ODD'S SPACE",11,Ui.Brush("#A9E8E3"));label.Margin=new Thickness(16,12,0,0);label.VerticalAlignment=VerticalAlignment.Top;hero.Children.Add(label);var stage=new Border{Background=Ui.Brush("#142844"),CornerRadius=new CornerRadius(20),Child=hero,Margin=new Thickness(0,0,0,10)};play.Children.Add(stage);
   var actionPanel=new StackPanel();Grid.SetRow(actionPanel,1);play.Children.Add(actionPanel);petState.Margin=new Thickness(2,0,0,7);actionPanel.Children.Add(petState);var tiles=new UniformGrid{Columns=4};foreach(Mood m in Enum.GetValues(typeof(Mood))){var mood=m;var b=Ui.Button(Ui.ActionName(m),delegate{pet.Paused=false;pet.SetMood(mood,true);pet.Say(Ui.ActionName(mood),2);Refresh();});b.FontSize=12;b.Padding=new Thickness(2);b.Margin=new Thickness(0,0,5,5);b.MinHeight=39;b.ToolTip=VoiceWindow.CommandFor(m);actions[m]=b;tiles.Children.Add(b);}actionPanel.Children.Add(tiles);var random=Ui.Button("Surprise me  ✦",delegate{pet.Auto();Refresh();});random.Margin=new Thickness(0);actionPanel.Children.Add(random);
   chat=new ChatWindow(pet);var chatCard=new Border{Background=Brushes.White,CornerRadius=new CornerRadius(20),Padding=new Thickness(16),Child=chat};Grid.SetColumn(chatCard,2);body.Children.Add(chatCard);
   voice=new VoiceWindow(pet);var voiceCard=new Border{Child=voice};Grid.SetRow(voiceCard,2);root.Children.Add(voiceCard);
