  public void Navigate(string destination){if(destination=="Settings"){overlay.Child=BuildSettings();overlay.Visibility=Visibility.Visible;}else{overlay.Visibility=Visibility.Collapsed;if(destination=="Chat")chat.Focus();if(destination=="Voice")voice.Focus();}}
  FrameworkElement BuildSettings(){var panel=new StackPanel();var top=new DockPanel();var done=Ui.Button("Done",delegate{overlay.Visibility=Visibility.Collapsed;pet.Preferences.Save();});DockPanel.SetDock(done,Dock.Right);top.Children.Add(done);top.Children.Add(Ui.Heading("Make it yours",23));panel.Children.Add(top);var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition());panel.Children.Add(grid);var habits=new StackPanel();grid.Children.Add(habits);AddToggle(habits,"Meow when petted",pet.Preferences.Sound,pet.SetSound);AddToggle(habits,"Wander around",pet.Preferences.Wander,delegate(bool v){pet.Preferences.Wander=v;pet.Auto();});AddToggle(habits,"Follow cursor",pet.Preferences.Follow,delegate(bool v){pet.Preferences.Follow=v;pet.Auto();});AddToggle(habits,"Perch on edges",pet.Preferences.Edges,delegate(bool v){pet.Preferences.Edges=v;});var sliders=new StackPanel{Margin=new Thickness(20,0,0,0)};Grid.SetColumn(sliders,1);grid.Children.Add(sliders);sliders.Children.Add(Ui.Text("Size"));var size=new Slider{Minimum=220,Maximum=480,Value=pet.Preferences.Size};System.Windows.Automation.AutomationProperties.SetName(size,"Odd size");size.ValueChanged+=delegate{pet.SetSize(size.Value);};size.MinHeight=30;size.Margin=new Thickness(0,2,0,8);sliders.Children.Add(size);sliders.Children.Add(Ui.Text("Walking pace"));var speed=new Slider{Minimum=20,Maximum=150,Value=pet.Preferences.Speed};System.Windows.Automation.AutomationProperties.SetName(speed,"Walking pace");speed.ValueChanged+=delegate{pet.Preferences.Speed=speed.Value;};speed.MinHeight=30;speed.Margin=new Thickness(0,2,0,8);sliders.Children.Add(speed);var bottom=new UniformGrid{Columns=2,Margin=new Thickness(0,8,0,0)};bottom.Children.Add(Ui.Button("Bring Odd back",pet.Home));bottom.Children.Add(Ui.Button("Hide dashboard",delegate{Suspend();Hide();}));panel.Children.Add(bottom);return panel;}
  void ShowHelp(){MessageBox.Show(this,"Drag Odd to move her · Right-drag to rotate · Scroll to resize.\nDouble-click Odd to reopen this dashboard.\n\nVoice: say Odd + an action. Hover an action for its English and Chinese phrases. Say ‘Odd, stop listening’ or ‘奥德，停止听我说话’ to stop.\n\nAudio is processed locally and never saved. Commands animate Odd; they do not dictate chat. Nearby voices may trigger actions.\n\nClosing this dashboard stops the microphone and any reply. Odd stays on your desktop.","Odd • Quick guide");}
  static void AddToggle(Panel panel,string label,bool value,Action<bool> change){var toggle=new CheckBox{Content=label,IsChecked=value};toggle.Checked+=delegate{change(true);};toggle.Unchecked+=delegate{change(false);};panel.Children.Add(toggle);}
  public void StopListening(){voice.StopListening();}public void Suspend(){StopListening();chat.Suspend();pet.Preferences.Save();}public void Shutdown(){exiting=true;voice.Shutdown();chat.Shutdown();updates.Stop();Close();}public void Status(Mood mood,bool paused){}
  void Refresh(){pause.Content=pet.Paused?"Resume":"Pause";hide.Content=pet.Hidden?"Show Odd":"Hide Odd";petState.Text=pet.Paused?"Taking a break": "Now · "+Ui.ActionName(pet.CurrentMood);micState.Text=pet.MicrophoneOn?"● Mic on":"Mic off";chatState.Text=chat.Summary;micStop.Visibility=pet.MicrophoneOn?Visibility.Visible:Visibility.Collapsed;foreach(var pair in actions){pair.Value.Background=pair.Key==pet.CurrentMood?Ui.Brush("#142844"):Ui.Tint;pair.Value.Foreground=pair.Key==pet.CurrentMood?Brushes.White:Ui.Ink;}}
 }
}
