  public static TextBlock Text(string text,double size=14,Brush color=null){return new TextBlock{Text=text,FontSize=size,Foreground=color??Ink,TextWrapping=TextWrapping.Wrap};}
  public static TextBlock Heading(string text,double size=28){var t=Text(text,size);t.FontWeight=FontWeights.SemiBold;t.Margin=new Thickness(0,0,0,8);return t;}
  public static Button Button(string label,Action action,bool primary=false){var b=new Button{Content=label};if(primary){b.Background=Teal;b.Foreground=Brushes.White;}b.Click+=delegate{action();};return b;}
  public static Border Card(UIElement child,Brush background=null){return new Border{Background=background??Brushes.White,CornerRadius=new CornerRadius(22),Padding=new Thickness(22),Margin=new Thickness(0,0,0,16),Child=child};}
  public static StackPanel Section(string title,string description=null){var s=new StackPanel();s.Children.Add(Heading(title,20));if(description!=null){var t=Text(description,14,Muted);t.Margin=new Thickness(0,0,0,14);s.Children.Add(t);}return s;}
  public static string ActionName(Mood mood){return mood==Mood.TongueOut?"Tongue out":mood==Mood.ScratchWall?"Scratch wall":mood==Mood.WiggleTail?"Wiggle tail":mood==Mood.Idle?"Relax":mood.ToString();}
 }

